"""Original RU narration. Heron: Pneumatics 21, 37, 50 (Woodcroft, 1851)."""
from pathlib import Path
import json
S=[]
def add(title,model,focus,text,key,source='Герон · Пневматика'):
 S.append(dict(title=title,model=model,focus=focus,text=text,key=key,source=source))
add('Монета запускает машину','coin','wide','''Этот автомат принимал монеты почти две тысячи лет назад. Бросаешь деньги — получаешь порцию воды. Ни электричества, ни компьютера, ни человека за прилавком. Сейчас мы снимем с него корпус и проследим за каждой деталью. А потом откроем храмовые двери одним огнём и запустим паровой шар. Все три устройства описаны в древнем тексте. Но самое интересное — почему мир с такими механизмами всё-таки не стал миром паровых заводов.''','2000 лет назад')
add('Сначала — честные правила','coin','explode','''Сразу договоримся: это учебные трёхмерные реконструкции, а не чудом найденные целые машины. Формы, цвета и размеры упрощены, чтобы было видно устройство. Мы отделяем то, что описано в источнике, от наших пояснений. У нас не будет инопланетян и фразы «учёные скрывают». Будут рычаг, вода, воздух и несколько очень умных способов заставить их выполнять работу. И да: знать принцип ещё не значит суметь построить надёжный серийный прибор.''','Описание ≠ сохранившийся прибор')
add('Кто такой Герон','coin','overview','''Герона Александрийского обычно относят к первому веку нашей эры. Его «Пневматика» — собрание описаний устройств, использующих воздух, жидкости и нагрев. Наш главный источник — перевод, изданный Беннетом Вудкрофтом в тысяча восемьсот пятьдесят первом году. Это важно: древний текст дошёл до нас через передачу и переводы. Мы можем разбирать описанную конструкцию, но не обязаны объявлять каждую такую машину массовым товаром на улицах Александрии.''','Александрия · I век н. э.')
add('Внутри автомата','coin','inside','''Посмотрим на сосуд. Снаружи виден только приёмник монеты и носик, из которого должна пойти вода. Внутри — резервуар, выходной канал и клапан. Пока отверстие закрыто, платить можно сколько угодно взглядом: вода не побежит. Рядом находится рычаг на опоре. Один его конец расширен в небольшую площадку для монеты. Другой соединён с крышкой, перекрывающей выход. Весь секрет начинается с равновесия этих частей.''','Три детали: рычаг · клапан · вода','Пневматика · §21')
add('Шаг 1. Монета','coin','lever','''Монета падает через прорезь и ложится на площадку. Появляется дополнительный вес. Рычаг поворачивается вокруг своей опоры, а противоположный конец поднимает запирающую крышку. Обратите внимание: монета не питает электрический двигатель и не включает тайный насос. Она меняет механическое равновесие. В этой конструкции деньги одновременно являются платой и физическим сигналом запуска. Убери их вес — и у машины больше нет причины оставаться открытой.''','01 · Вес меняет равновесие','Пневматика · §21')
add('Шаг 2. Вода','coin','valve','''Крышка приподнялась, выход освободился, вода пошла по каналу к носику. Движение воды здесь обеспечивается её положением и действием тяжести. Сам по себе рычаг не создаёт запас жидкости и не заставляет полный бак возникать из ничего. Цветная подсветка показывает путь потока, а не скрытый современный трубопровод. Синее — вода, золотое — управляющие детали. Так проще увидеть связь между маленьким движением монеты и вполне заметным результатом снаружи.''','02 · Клапан открывает выход','Пневматика · §21')
add('Шаг 3. Автоматический сброс','coin','reset','''Рычаг наклонился, и монета соскальзывает с площадки. Дополнительный вес исчезает. Запирающая крышка возвращается вниз и перекрывает воду. Теперь система готова принять следующую монету. Вот весь цикл: ожидание, запуск, выдача, остановка. Никакой второй команды от покупателя не требуется. Именно самостоятельное завершение делает устройство особенно интересным: оно не просто открывает кран, а возвращается в исходное состояние. Но резервуар всё равно придётся наполнять, а деньги — извлекать.''','03 · Монета упала — вода остановилась','Пневматика · §21')
add('Чего автомат не умел','coin','detail','''Не стоит приписывать этой схеме возможности современной кассы. В описанном механизме нет банковской проверки монеты и программы, измеряющей точный объём с помощью датчика. На результат влияют настройка рычага, время до соскальзывания, отверстие и уровень воды. Это наша инженерная оценка упрощённой схемы, а не найденный древний паспорт точности. Устройство впечатляет и без сказки о совершенном автомате. Хорошая идея не обязана быть идеальной, чтобы стать хорошей идеей.''','Механический запуск ≠ проверка денег')
add('Теперь — дверь без рук','door','wide','''А теперь представьте другой опыт. Перед небольшим храмом зажигают огонь на алтаре. Чуть позже двери начинают открываться сами. Снаружи почти ничего не объясняет происходящее. Но под площадкой скрыта цепочка преобразований. Мы покажем её в разрезе: нагретый воздух, сосуд с водой, трубка, подвешенная ёмкость, цепи и противовес. Важно не перепутать этот механизм с паровым шаром. Двери в данном описании приводит в движение другая система.''','Огонь → открытые двери','Пневматика · §37')
add('Шаг 1. Воздух нагревается','door','heat','''Начинаем с алтаря и соединённого с ним замкнутого объёма. Огонь нагревает воздух. Тот расширяется и действует на жидкость в связанном сосуде. Вода получает возможность уходить через трубку в подвешенную ёмкость. Здесь не нужно представлять миниатюрный паровоз под храмом. Главные участники — нагрев воздуха и перенос воды. В нашей модели красные частицы условно обозначают нагретый воздух. Это поясняющая графика: настоящий воздух не начинает светиться красным.''','01 · Нагрев → изменение давления','Пневматика · §37')
add('Шаг 2. Вода становится грузом','door','bucket','''Вода поступает в подвешенную ёмкость, и та становится тяжелее. Перед нами простое, но красивое превращение: тепло изменяет состояние воздуха, воздух перемещает воду, а вода добавляет вес. Заполненная ёмкость опускается и натягивает цепь. Для зрителя сверху всё ещё происходит одно событие — дверь открывается. Для инженера снизу это уже несколько причин, связанных последовательно. Если одна из них не сработает, вся демонстрация остановится.''','02 · Вода увеличивает вес','Пневматика · §37')
add('Шаг 3. Вес поворачивает двери','door','open','''Цепи связаны с осями дверей. Когда груз опускается, оси поворачиваются и створки расходятся. Другие цепи соединены с противовесом, который нужен для обратного движения. Мы ускорили процесс на экране, чтобы его было удобно разбирать. Это не измеренная скорость настоящего древнего устройства. Заметьте главное: огонь не тянет дверь непосредственно. Между пламенем и створкой есть несколько посредников. Именно их согласованная работа и создаёт эффект автоматического действия.''','03 · Груз → цепи → оси','Пневматика · §37')
add('Как двери закрывались','door','return','''В тексте Герона описан и возврат после прекращения нагрева. По мере изменения состояния воздуха вода возвращается из подвешенного сосуда. Он становится легче, противовес получает перевес, и двери закрываются. Детали герметичности, трубок и трения здесь критичны. Учебная анимация не доказывает, что любой похожий макет заработает с первой попытки. Но она показывает замысел: переключение потока воды меняет баланс грузов, а баланс грузов управляет положением дверей.''','Возврат воды → противовес закрывает дверь','Пневматика · §37')
add('Почему это ещё не умный дом','door','overview','''В современном доме ту же задачу можно решить датчиком, контроллером и электроприводом. Древняя схема обходилась без них, потому что нужные связи были заложены в геометрию и физику деталей. Но называть её полноценным умным домом было бы рекламным преувеличением. Она решает конкретную задачу конкретным способом. И именно это полезно увидеть: автоматизация началась не с приложения на телефоне. Иногда программа буквально состоит из формы трубки и массы подвешенного ведра.''','Логика заложена в конструкции')
add('Самый узнаваемый опыт','steam','wide','''Третий аппарат выглядит как маленький фантастический двигатель: шар между опорами, под ним сосуд, по сторонам — изогнутые трубки. При нагреве воды пар поступает в шар и выходит через сопла. Шар вращается. Такой прибор называют эолипилом. Герон описал его в «Пневматике», а музейные коллекции показывают поздние демонстрационные модели. Перед нами не найденный древний промышленный мотор, а наглядный принцип получения движения из направленной струи.''','Эолипил · пар заставляет шар вращаться','Пневматика · §50')
add('Почему он крутится','steam','jets','''Посмотрите на направления сопел. Струи выходят в стороны, а реакция действует на сам шар. Поскольку сопла расположены относительно оси, возникает вращающий момент. Это можно понять без магических слов: выбрасывая пар в одном направлении, устройство получает воздействие в противоположном. На экране траектории пара увеличены и подсвечены. Настоящий поток сложнее этих аккуратных полос, но направления показаны для объяснения причины вращения. Поверни сопла иначе — и характер движения изменится.''','Направленная струя → вращающий момент')
add('Где здесь полезная работа','steam','detail','''Вращение есть. Но завод — это не просто что-нибудь, что крутится. Чтобы машина постоянно выполняла полезную работу, нужны подходящие мощность, расход топлива, прочность, уплотнения, обслуживание и передача движения к нагрузке. Наш шар демонстрирует физический принцип. Из одного факта его вращения нельзя заключить, что рядом уже мог стоять практичный паровой ткацкий станок. Между удачным опытом и удобным производственным двигателем лежит большая инженерная работа.''','Демонстрация принципа ≠ промышленный двигатель')
add('Почему не случилась революция','steam','overview','''Вот теперь вернёмся к вопросу из начала. Почему такие идеи не превратили древность в эпоху заводов? Честный ответ не помещается в одну эффектную фразу. Само наличие описания ещё ничего не говорит о цене, распространённости и хозяйственной выгоде устройства. Для массовой технологии важна целая система производства и применения. Мы не будем объявлять одну причину окончательным объяснением истории. Надёжнее отделить доказанное устройство от красивого альтернативного сценария о мире, который мог бы получиться.''','Изобретение — ещё не массовая технология')
add('Что объединяет три машины','all','wide','''У трёх приборов разные источники действия. В автомате сигналом служит вес монеты, а вода течёт за счёт своего положения. В дверях нагрев запускает перенос воды и меняет вес груза. В эолипиле паровые струи создают вращение. Но подход один: найти физическую связь и использовать её последовательно. Нам не требуется приписывать древним современные компьютеры, чтобы оценить точность этой мысли. Они решали задачи теми средствами, которые умели описывать и собирать.''','Сигнал → действие → результат')
add('Разница между чудом и механизмом','coin','explode','''Теперь снова взгляните на автомат. В начале мы видели только прорезь и струю. Сейчас за ними видны рычаг, клапан и возврат. Эффект не стал менее красивым после объяснения. Наоборот: появилось понимание, какую часть задачи выполняет каждая деталь. Это и есть смысл нашей реконструкции. Не убедить, что история невозможна, а показать, как возможное было устроено. А заодно не спутать древнее описание с современной фантазией, даже если фантазия очень блестящая.''','Объяснение делает изобретение интереснее')
add('Как мы это проверяли','all','overview','''В описании выпуска оставлены источники: разделы двадцать один, тридцать семь и пятьдесят «Пневматики», а также музейные пояснения к эолипилу. Модели сделаны специально для этого объяснения. Их цвета и пропорции условны, детали движения упрощены, а промежутки времени ускорены. Это не видео действующего археологического оригинала и не инструкция для сборки горячего аппарата. Но причинную цепочку теперь можно проверить самому: откуда взялось движение и что именно его останавливает.''','Источники · границы реконструкции')
add('Твоя следующая машина','all','final','''Из всех трёх устройств мне больше всего нравится автомат с монетой. Потому что в нём один маленький предмет сразу выполняет две роли: сообщает о плате и запускает физический процесс. А какая машина удивила тебя сильнее: торговый автомат, двери от огня или вращающийся паровой шар? Напиши в комментариях. Если хочется больше таких разборов, следующий механизм будем не просто рассматривать снаружи. Снова разберём его до деталей и соберём понимание обратно.''','Что разобрать следующим?')
root=Path(__file__).resolve().parent
(root/'script.json').write_text(json.dumps(S,ensure_ascii=False,indent=2))
(root/'NARRATION.md').write_text('# Герон: автоматы без электричества\n\n'+'\n\n'.join(f'## {i+1}. {s["title"]}\n\n{s["text"]}' for i,s in enumerate(S)))
print('Words',sum(len(s['text'].split()) for s in S))
